func dDoSPreventionDecodeIndex(raw json.RawMessage, location string, idxKind string, diagnostics *diag.Diagnostics) (int, bool) {
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 || dDoSPreventionJSONNull(trimmed) {
		diagnostics.AddError("Malformed DDoS prevention result", location+" did not contain a non-null integer idx.")
		return 0, false
	}
	if trimmed[0] != '-' && (trimmed[0] < '0' || trimmed[0] > '9') {
		diagnostics.AddError("Malformed DDoS prevention result", location+" contained a non-integer idx.")
		return 0, false
	}
	var number json.Number
	if err := json.Unmarshal(trimmed, &number); err != nil {
		diagnostics.AddError("Malformed DDoS prevention result", location+" contained a non-integer idx.")
		return 0, false
	}
	value64, err := number.Int64()
	if err != nil || value64 <= 0 || int64(int(value64)) != value64 {
		diagnostics.AddError("Malformed DDoS prevention result", location+" contained an idx that was not a positive integer.")
		return 0, false
	}
	return int(value64), true
}

