func dDoSPreventionJSONNull(raw json.RawMessage) bool {
	return bytes.Equal(bytes.TrimSpace(raw), []byte("null"))
}

// RejectItemNullUnlessNullable reports a malformed-result diagnostic when a
// collection-item field is present in the remote response as an explicit JSON
// null but the pinned schema does not mark the field nullable. A missing key
// is not rejected here (optional omission is handled by the decode helpers).
func dDoSPreventionRejectItemNullUnlessNullable(object map[string]json.RawMessage, key string, allowNull bool, location string, diagnostics *diag.Diagnostics) {
	raw, ok := object[key]
	if !ok {
		return
	}
	if dDoSPreventionJSONNull(raw) && !allowNull {
		diagnostics.AddError("Malformed DDoS prevention result", location+" "+key+" was null, which the pinned schema does not mark nullable.")
	}
}
func dDoSPreventionValidateConfiguredIpException(ctx context.Context, wrapper types.Object) diag.Diagnostics {
	var diagnostics diag.Diagnostics
	if wrapper.IsNull() || wrapper.IsUnknown() {
		return diagnostics
	}
	var model struct {
		Items types.List `tfsdk:"item"`
	}
	diagnostics.Append(wrapper.As(ctx, &model, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() || model.Items.IsNull() || model.Items.IsUnknown() {
		return diagnostics
	}
	var items []ipExceptionItemModel
	diagnostics.Append(model.Items.ElementsAs(ctx, &items, false)...)
	if diagnostics.HasError() {
		return diagnostics
	}
	for index, item := range items {
		location := fmt.Sprintf("ip_exception item %d", index+1)
		if item.Ip.IsNull() {
			diagnostics.AddError("Invalid DDoS prevention ip_exception", location+" ip is required.")
		}
	}
	return diagnostics
}

func dDoSPreventionBuildConfiguredIpException(ctx context.Context, configured, planned types.Object, diagnostics diag.Diagnostics) (ipExceptionOwnedList, diag.Diagnostics) {
	if configured.IsNull() {
		return ipExceptionOwnedList{}, diagnostics
	}
	if configured.IsUnknown() {
		diagnostics.AddError("Unknown DDoS prevention ip_exception", "The ip_exception ownership wrapper must be known during apply.")
		return ipExceptionOwnedList{}, diagnostics
	}
	if planned.IsNull() || planned.IsUnknown() {
		diagnostics.AddError("Unknown DDoS prevention ip_exception", "The planned ip_exception ownership wrapper must be known during apply.")
		return ipExceptionOwnedList{}, diagnostics
	}
	var configWrapper, planWrapper struct {
		Items types.List `tfsdk:"item"`
	}
	diagnostics.Append(configured.As(ctx, &configWrapper, basetypes.ObjectAsOptions{})...)
	diagnostics.Append(planned.As(ctx, &planWrapper, basetypes.ObjectAsOptions{})...)
	if diagnostics.HasError() {
		return ipExceptionOwnedList{}, diagnostics
	}
	if configWrapper.Items.IsUnknown() || planWrapper.Items.IsUnknown() {
		diagnostics.AddError("Unknown DDoS prevention ip_exception", "The ip_exception item blocks must be known during apply.")
		return ipExceptionOwnedList{}, diagnostics
	}
	if configWrapper.Items.IsNull() {
		return ipExceptionOwnedList{Set: true, Items: []string{}}, diagnostics
	}
	var configItems, planItems []ipExceptionItemModel
	diagnostics.Append(configWrapper.Items.ElementsAs(ctx, &configItems, false)...)
	if planWrapper.Items.IsNull() {
		if len(configItems) != 0 {
			diagnostics.AddError("Invalid DDoS prevention ip_exception", "The planned item list unexpectedly became null.")
		}
		return ipExceptionOwnedList{Set: true, Items: []string{}}, diagnostics
	}
	diagnostics.Append(planWrapper.Items.ElementsAs(ctx, &planItems, false)...)
	if diagnostics.HasError() {
		return ipExceptionOwnedList{}, diagnostics
	}
	if len(configItems) != len(planItems) {
		diagnostics.AddError("Invalid DDoS prevention ip_exception", "Configured and planned item counts differ.")
		return ipExceptionOwnedList{}, diagnostics
	}
	items := make([]string, 0, len(configItems))
	for index := range configItems {
		configuredItem := configItems[index]
		plannedItem := planItems[index]
		location := fmt.Sprintf("ip_exception item %d", index+1)
		if configuredItem.Ip.IsNull() {
			diagnostics.AddError("Invalid DDoS prevention ip_exception", "The required "+location+" ip is null.")
			continue
		}
		value := ""
		if configuredItem.Ip.IsUnknown() {
			if plannedItem.Ip.IsNull() || plannedItem.Ip.IsUnknown() {
				diagnostics.AddError("Unknown DDoS prevention ip_exception", "The configured "+location+" ip is still unknown during apply.")
				continue
			}
			value = plannedItem.Ip.ValueString()
		} else {
			value = configuredItem.Ip.ValueString()
		}
		items = append(items, value)
	}
	return ipExceptionOwnedList{Set: true, Items: items}, diagnostics
}

func dDoSPreventionDecodeIpException(raw json.RawMessage) ([]string, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	if len(raw) == 0 {
		return []string{}, diagnostics
	}
	if dDoSPreventionJSONNull(raw) {
		diagnostics.AddError("Malformed DDoS prevention result", "The successful API result contained null ip_exception instead of an array.")
		return nil, diagnostics
	}
	var rawItems []json.RawMessage
	if err := json.Unmarshal(raw, &rawItems); err != nil {
		diagnostics.AddError("Malformed DDoS prevention result", "The successful API result contained a non-array ip_exception value.")
		return nil, diagnostics
	}
	items := make([]string, 0, len(rawItems))
	for position, rawItem := range rawItems {
		location := fmt.Sprintf("ip_exception item %d", position+1)
		if dDoSPreventionJSONNull(rawItem) {
			diagnostics.AddError("Malformed DDoS prevention result", location+" was null instead of a string.")
			continue
		}
		var value string
		if err := json.Unmarshal(rawItem, &value); err != nil {
			diagnostics.AddError("Malformed DDoS prevention result", location+" was not a string.")
			continue
		}
		items = append(items, value)
	}
	if diagnostics.HasError() {
		return nil, diagnostics
	}
	return items, diagnostics
}

func dDoSPreventionIpExceptionWrapperValue(items []string) (types.Object, diag.Diagnostics) {
	var diagnostics diag.Diagnostics
	elements := make([]attr.Value, 0, len(items))
	for _, item := range items {
		object, objectDiagnostics := types.ObjectValue(ipExceptionItemAttributeTypes, map[string]attr.Value{"ip": types.StringValue(item)})
		diagnostics.Append(objectDiagnostics...)
		elements = append(elements, object)
	}
	list, listDiagnostics := types.ListValue(types.ObjectType{AttrTypes: ipExceptionItemAttributeTypes}, elements)
	diagnostics.Append(listDiagnostics...)
	wrapper, wrapperDiagnostics := types.ObjectValue(ipExceptionWrapperAttributeTypes, map[string]attr.Value{"item": list})
	diagnostics.Append(wrapperDiagnostics...)
	return wrapper, diagnostics
}
